// lib/calc.js (generated by scripts/convert/build-calc.py) behaves as the modules of post/lab it is made
// from, on a sample of terms of each calculus. The comparison with post/lab is skipped where post/lab is
// not at hand (outside the formal-computation repository); the checks of known results always run.
// Run with: node --test post/localization-semantics-1/figures/
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import { CALC, SKI, TREE, NET, GRAPH } from './lib/calc.js';

const LAB = new URL('../../lab/', import.meta.url);
const here = ['ski.js', 'tree.js', 'net.js', 'graph.js'].every((f) => fs.existsSync(new URL(f, LAB)));
let lab = null;
if (here) {
  // the UMD files attach to globalThis.CALC under Node; load them in their order
  const require = createRequire(import.meta.url);
  for (const f of ['ski.js', 'tree.js', 'net.js', 'graph.js']) require(new URL(f, LAB).pathname);
  lab = globalThis.CALC;
}

const SKI_TERMS = ['I', 'S K K', 'S K S', 'K I', 'K (S K K)', 'K', 'S K K a', 'K a (I b)', 'K a (K a)', 'I a', 'K a b',
  'I I', 'K I a', 'S I I (S I I)', 'K a (S I I (S I I))', 'S (K S) K x y z', 'S (S K K) (S K K) x', 'S K K (K a b)'];
const TREE_TERMS = ['I', 'S K K', 'S K (△K)', 'K I', 'K (S K K)', 'K', 'S K K a', 'K a (I b)', 'K a (△a)', 'K a (K b (△b))',
  'ω ω', 'I ω (I ω)', 'K a (ω ω)', 'triage(x, triage(y, K z, △), △) (triage(K △, K (K △), K I) (S K K))', '△ △ △ △', 'K I (△I)'];
const NET_TERMS = ['K a (I b)', 'I x', 'S K K a', 'K I a', 'K a b', '△△ u v', 'I (K a b)'];

function summary(C, s, max) {
  const t = C.parse(s), run = C.run(t, 'outer', max), inner = C.run(t, 'inner', max);
  return {
    print: C.print(t), key: C.key(t), html: C.print(t, { html: true, mark: C.redexes(t)[0] }),
    redexes: C.redexes(t).map((r) => [r.at, r.rule]),
    outer: run.map((u) => C.print(u)), inner: inner.map((u) => C.print(u)),
    normal: C.isNormal(run[run.length - 1]), outcome: C.isOutcome(run[run.length - 1])
  };
}

test('the module exports the four calculi', () => {
  assert.equal(CALC.ski, SKI); assert.equal(CALC.tree, TREE); assert.equal(CALC.net, NET); assert.equal(CALC.graph, GRAPH);
  assert.ok(!('CALC' in globalThis) || globalThis.CALC !== CALC, 'nothing attached to globalThis');
});

test('known results (post/lab/README.md)', () => {
  const nf = (C, s, m = 'outer') => { const r = C.run(C.parse(s), m, 200); return C.print(r[r.length - 1]); };
  assert.equal(nf(SKI, 'S K K x'), 'x');
  assert.equal(nf(SKI, 'K I x y'), 'y');
  assert.equal(nf(TREE, 'S K K a'), 'a');
  assert.equal(TREE.run(TREE.parse('S K K a'), 'outer', 40).length - 1, 2);
  assert.equal(nf(TREE, 'triage(x, triage(y, K z, △), △) (triage(K △, K (K △), K I) (S K (△K)))'), 'z');
  // interactions per bench cell: I x costs 7, K x 1, K x y 3
  const count = (s) => NET.run(NET.parse(s), 'outer', 2000).length - 1;
  assert.equal(count('I x'), 7);
  assert.equal(count('K x'), 1);
  assert.equal(count('K x y'), 3);
});

test('combinatory logic agrees with post/lab', { skip: !here && 'post/lab not found' }, () => {
  for (const s of SKI_TERMS) assert.deepEqual(summary(SKI, s, 40), summary(lab.ski, s, 40), s);
});

test('tree calculus agrees with post/lab', { skip: !here && 'post/lab not found' }, () => {
  for (const s of TREE_TERMS) assert.deepEqual(summary(TREE, s, 60), summary(lab.tree, s, 60), s);
});

test('interaction nets agree with post/lab', { skip: !here && 'post/lab not found' }, () => {
  for (const s of NET_TERMS) {
    const f = (C) => {
      const run = C.run(C.parse(s), 'outer', 400), last = run[run.length - 1];
      return { n: run.length, reads: run.map((n) => C.print(n, { html: true })), key: C.key(last), size: C.size(last), layout: C.layoutNet(run[0]) };
    };
    assert.deepEqual(f(NET), f(lab.net), s);
  }
});

test('graphs and bundle layouts agree with post/lab', { skip: !here && 'post/lab not found' }, () => {
  const terms = ['S K K a', 'K a (I b)', 'I a', 'a', 'I I', 'I', 'ω ω', 'I ω (I ω)', 'K ω (△ω) (I ω)', 'ω (I ω)', 'ω (K ω (△ω))'];
  for (const [G, C] of [[GRAPH, TREE], [lab.graph, lab.tree]]) assert.ok(G && C);
  const strip = (g) => JSON.parse(JSON.stringify(g, (k, v) => (k === 't' ? undefined : v)));
  const mine = GRAPH.reductionGraph(TREE, terms.map((s) => TREE.parse(s)), { closed: true });
  const theirs = lab.graph.reductionGraph(lab.tree, terms.map((s) => lab.tree.parse(s)), { closed: true });
  assert.deepEqual(strip(mine), strip(theirs));
  for (const orientation of ['wide', 'tall']) {
    const o = { orientation, layering: orientation === 'tall' ? 'nearest' : 'longest', rings: true, slots: true, curves: true };
    assert.deepEqual(strip(GRAPH.layoutBundle(mine, o)), strip(lab.graph.layoutBundle(theirs, o)), orientation);
  }
  const nm = GRAPH.reductionGraph(NET, NET.compile(TREE.parse('K a (I b)')), { max: 400, simple: true });
  const nt = lab.graph.reductionGraph(lab.net, lab.net.compile(lab.tree.parse('K a (I b)')), { max: 400, simple: true });
  assert.deepEqual(strip(nm), strip(nt));
  assert.deepEqual(GRAPH.runPath(NET, nm.states[0].t, 'random', { max: 400, random: NET.rng(3) }).keys,
    lab.graph.runPath(lab.net, nt.states[0].t, 'random', { max: 400, random: lab.net.rng(3) }).keys);
});
